package com.cloudcostai.aws.service.impl;

import java.math.BigDecimal;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Derives structured, machine-readable evidence for a stored recommendation from the persisted
 * human-readable reason and title text.
 *
 * <p>The stored reason text is generated by {@link AwsRecommendationServiceImpl} using a fixed,
 * well-known format, so it can be parsed deterministically without guessing or fabricating values.
 * When a value is not present in the stored evidence the corresponding field is {@code null} so the
 * client can render an explicit "Insufficient Data" state instead of a misleading placeholder.
 */
final class RecommendationEvidenceParser {
    static final String SAVINGS_BASIS_HEURISTIC = "HEURISTIC_ESTIMATE";
    static final String SAVINGS_BASIS_INSUFFICIENT = "INSUFFICIENT_DATA";

    private static final Pattern COST_SHARE = Pattern.compile("cost share=([\\d.,]+)\\s*%", Pattern.CASE_INSENSITIVE);
    private static final Pattern PERIOD_TOTAL_COST = Pattern.compile("total cost=([\\d.,]+)", Pattern.CASE_INSENSITIVE);
    private static final BigDecimal CONCENTRATION_THRESHOLD = new BigDecimal("25.00");

    private RecommendationEvidenceParser() {
    }

    static Evidence parse(String reason, String title, BigDecimal potentialSavings) {
        BigDecimal costShare = null;
        BigDecimal periodTotalCost = null;
        BigDecimal threshold = null;
        if (reason != null && !reason.isBlank() && isCostConcentration(reason)) {
            costShare = firstDecimal(COST_SHARE, reason);
            periodTotalCost = firstDecimal(PERIOD_TOTAL_COST, reason);
            if (costShare != null) {
                threshold = CONCENTRATION_THRESHOLD;
            }
        }
        String resourceState = resourceState(title);
        String savingsBasis = potentialSavings != null && potentialSavings.signum() > 0
            ? SAVINGS_BASIS_HEURISTIC
            : SAVINGS_BASIS_INSUFFICIENT;
        return new Evidence(costShare, periodTotalCost, threshold, resourceState, savingsBasis);
    }

    private static boolean isCostConcentration(String reason) {
        return reason != null && reason.toLowerCase().contains("cost concentration");
    }

    private static String resourceState(String title) {
        if (title == null) return null;
        String normalized = title.toLowerCase();
        if (normalized.contains("unattached")) return "UNATTACHED";
        if (normalized.contains("stopped")) return "STOPPED";
        return null;
    }

    private static BigDecimal firstDecimal(Pattern pattern, String value) {
        Matcher matcher = pattern.matcher(value);
        if (!matcher.find()) return null;
        String raw = matcher.group(1).replace(",", "").trim();
        if (raw.isEmpty()) return null;
        try {
            return new BigDecimal(raw);
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

    record Evidence(BigDecimal costSharePercentage, BigDecimal periodTotalCost, BigDecimal concentrationThreshold,
                    String resourceState, String savingsBasis) {
    }
}
